const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const video=$('#heroVideo'), enter=$('#enterLayer'), hero=$('.hero'), sound=$('#soundBtn');
$('#enterBtn').addEventListener('click',async()=>{enter.classList.add('hide');hero.classList.add('playing');video.muted=false;try{await video.play()}catch{video.muted=true;await video.play();sound.querySelector('span').textContent='OFF'}});
sound.addEventListener('click',()=>{video.muted=!video.muted;sound.querySelector('span').textContent=video.muted?'OFF':'ON'});
video.addEventListener('ended',()=>{hero.classList.add('playing')});
const menu=$('#menuPanel'); $('#menuBtn').onclick=()=>{menu.classList.add('open');menu.setAttribute('aria-hidden','false')}; $('#menuClose').onclick=closeMenu; $$('#menuPanel a').forEach(a=>a.onclick=closeMenu); function closeMenu(){menu.classList.remove('open');menu.setAttribute('aria-hidden','true')}
const search=$('#searchPanel'), input=$('#siteSearch'), results=$('#searchResults'); $('#searchBtn').onclick=()=>{search.classList.add('open');search.setAttribute('aria-hidden','false');setTimeout(()=>input.focus(),500)}; $('#searchClose').onclick=()=>{search.classList.remove('open');search.setAttribute('aria-hidden','true')};
input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();results.innerHTML='';if(!q)return;const found=$$('[data-search]').filter(x=>x.dataset.search.toLowerCase().includes(q)||x.textContent.toLowerCase().includes(q));results.innerHTML=found.length?found.map(x=>`<div class="search-result">${x.querySelector('h3').textContent}</div>`).join(''):'<div class="search-result">No results found.</div>'});
