Object.assign(copy.en,{installApp:'Install App'});Object.assign(copy.fa,{installApp:'نصب اپلیکیشن'});Object.assign(copy.ar,{installApp:'تثبيت التطبيق'});
const supportedLanguages=['en','fa','ar'];
function applyLanguage(lang,{updateUrl=false}={}){
  if(!supportedLanguages.includes(lang))lang='en';
  document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';
  $$('[data-lang]').forEach(x=>x.classList.toggle('active',x.dataset.lang===lang));
  $$('[data-i18n]').forEach(el=>{const v=copy[lang][el.dataset.i18n];if(v)el.textContent=v});
  document.querySelector('meta[name="description"]').content={en:'Fourth Dimension Studio — architecture, AI, motion, web and digital products.',fa:'استودیو بعد چهارم؛ معماری، هوش مصنوعی، موشن، وب و محصولات دیجیتال.',ar:'استوديو البعد الرابع للعمارة والذكاء الاصطناعي والموشن والويب والمنتجات الرقمية.'}[lang];
  if(updateUrl){const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState({},'',url)}
}
const initialLanguage=supportedLanguages.includes(new URLSearchParams(location.search).get('lang'))?new URLSearchParams(location.search).get('lang'):'en';
$$('[data-lang]').forEach(b=>b.onclick=()=>applyLanguage(b.dataset.lang,{updateUrl:true}));
applyLanguage(initialLanguage);
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.animate([{opacity:0,transform:'translateY(60px) scale(.98)'},{opacity:1,transform:'none'}],{duration:850,easing:'cubic-bezier(.2,.8,.2,1)',fill:'both'})}),{threshold:.12});$$('.depth-section').forEach(s=>io.observe(s));

const serviceLabels={
  en:{architecture:'Architecture',ai:'AI & Content Creation',motion:'Teasers & Motion',web:'Web & App Design',automation:'Automation & Agents',editorial:'Articles & Books'},
  fa:{architecture:'معماری',ai:'هوش مصنوعی و تولید محتوا',motion:'تیزر و موشن',web:'طراحی سایت و اپلیکیشن',automation:'اتوماسیون و ایجنت',editorial:'مقاله و کتاب'},
  ar:{architecture:'الهندسة المعمارية',ai:'الذكاء الاصطناعي وصناعة المحتوى',motion:'الإعلانات والموشن',web:'تصميم المواقع والتطبيقات',automation:'الأتمتة والوكلاء',editorial:'المقالات والكتب'}
};
function setVideoLabels(lang){$$('[data-service]').forEach(el=>el.textContent=serviceLabels[lang][el.dataset.service])}
$$('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setVideoLabels(btn.dataset.lang)));
video.addEventListener('timeupdate',()=>{
  const t=video.currentTime;
  $$('[data-group]').forEach(el=>{
    const g=el.dataset.group;
    const show=(g==='middle'&&t>=9.25&&t<11.70)||(g==='upper'&&t>=11.70&&t<14.20)||(g==='lower'&&t>=14.20&&t<16.80);
    el.classList.toggle('visible',show);
  });
});
video.addEventListener('ended',()=>$$('[data-group]').forEach(el=>el.classList.remove('visible')));
video.addEventListener('play',()=>hero.classList.add('video-active'));
video.addEventListener('ended',()=>hero.classList.remove('video-active'));

const quickInput=$('#quickSearch'),quickResults=$('#quickSearchResults'),quickShell=$('.quick-search-shell'),quickClear=$('#quickSearchClear');
const quickItems=[
  {key:'s1',url:'service.html?service=architecture',terms:'architecture interior exterior design bim revit rendering معماری داخلی خارجی طراحی عمارة داخلي خارجي'},
  {key:'s2',url:'service.html?service=ai',terms:'ai artificial intelligence ai content design هوش مصنوعی تولید محتوا الذكاء الاصطناعي المحتوى'},
  {key:'s3',url:'service.html?service=motion',terms:'video teaser logo motion advertising film ویدئو تیزر لوگوموشن تبلیغات فيديو موشن'},
  {key:'s4',url:'service.html?service=web',terms:'web website wordpress app application design سایت اپلیکیشن موقع تطبيق'},
  {key:'s5',url:'service.html?service=automation',terms:'automation agent make composio workflow اتوماسیون ایجنت أتمتة وكلاء'},
  {key:'s6',url:'service.html?service=editorial',terms:'articles books journal pdf مقاله کتاب مقالات كتب'}
];
let activeLanguage=initialLanguage;
function renderQuickSearch(){
  const q=quickInput.value.trim().toLocaleLowerCase();quickShell.classList.toggle('has-value',Boolean(q));quickResults.textContent='';
  if(!q){quickResults.classList.remove('open');quickInput.setAttribute('aria-expanded','false');return}
  const found=quickItems.filter(item=>(item.terms+' '+copy[activeLanguage][item.key]).toLocaleLowerCase().includes(q));
  if(!found.length){const empty=document.createElement('div');empty.className='quick-search-empty';empty.textContent=copy[activeLanguage].noResults;quickResults.append(empty)}
  found.forEach(item=>{const link=document.createElement('a');link.className='quick-search-result';link.href=item.url;link.setAttribute('role','option');const name=document.createElement('span');name.textContent=copy[activeLanguage][item.key];const type=document.createElement('small');type.textContent=copy[activeLanguage].searchType;link.append(name,type);quickResults.append(link)});
  quickResults.classList.add('open');quickInput.setAttribute('aria-expanded','true');
}
quickInput.addEventListener('input',renderQuickSearch);quickInput.addEventListener('focus',()=>{if(quickInput.value.trim())renderQuickSearch()});
quickClear.addEventListener('click',()=>{quickInput.value='';renderQuickSearch();quickInput.focus()});
quickInput.addEventListener('keydown',e=>{if(e.key==='Escape'){quickResults.classList.remove('open');quickInput.setAttribute('aria-expanded','false')}if(e.key==='Enter'){const first=quickResults.querySelector('a');if(first)location.href=first.href}});
document.addEventListener('click',e=>{if(!quickShell.contains(e.target)){quickResults.classList.remove('open');quickInput.setAttribute('aria-expanded','false')}});
$$('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>{activeLanguage=btn.dataset.lang;quickInput.placeholder=copy[activeLanguage].searchPlaceholder;renderQuickSearch()}));
quickInput.placeholder=copy[activeLanguage].searchPlaceholder;
setVideoLabels(initialLanguage);

if(matchMedia('(hover:hover) and (pointer:fine)').matches){$$('.glass-card').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--tilt-y',`${((e.clientX-r.left)/r.width-.5)*7}deg`);card.style.setProperty('--tilt-x',`${(.5-(e.clientY-r.top)/r.height)*7}deg`);card.classList.add('tilting')});card.addEventListener('pointerleave',()=>{card.classList.remove('tilting');card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y')})})}
$$('[data-connect="later"]').forEach(link=>link.addEventListener('click',e=>e.preventDefault()));
let installPrompt;const installButton=$('#installApp');window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;installButton.hidden=false});installButton.addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;installButton.hidden=true});window.addEventListener('appinstalled',()=>{installButton.hidden=true});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));

const seoCopy={
  en:{title:'Fourth Dimension Studio | Architecture, AI & Digital Design',description:'Fourth Dimension Studio creates architecture, BIM, AI content, motion, websites, applications and intelligent automation for international clients.',locale:'en_US'},
  fa:{title:'استودیو بُعد چهارم | معماری، هوش مصنوعی و طراحی دیجیتال',description:'استودیو بُعد چهارم در زمینه معماری، BIM، تولید محتوای هوش مصنوعی، موشن، سایت، اپلیکیشن و اتوماسیون هوشمند فعالیت می‌کند.',locale:'fa_IR'},
  ar:{title:'استوديو البعد الرابع | العمارة والذكاء الاصطناعي والتصميم الرقمي',description:'استوديو دولي للعمارة وBIM وصناعة المحتوى بالذكاء الاصطناعي والموشن والمواقع والتطبيقات والأتمتة الذكية.',locale:'ar_AR'}
};
function applyLanguageSeo(lang){
  const seo=seoCopy[lang]||seoCopy.en;
  const base='https://fourth-dimension-studio.infinityfreeapp.com/';
  const canonical=lang==='en'?`${base}?lang=en`:`${base}?lang=${lang}`;
  document.title=seo.title;
  document.querySelector('meta[name="description"]').content=seo.description;
  document.querySelector('link[rel="canonical"]').href=canonical;
  document.querySelector('meta[property="og:title"]').content=seo.title;
  document.querySelector('meta[property="og:description"]').content=seo.description;
  document.querySelector('meta[property="og:url"]').content=canonical;
  let locale=document.querySelector('meta[property="og:locale"]');if(!locale){locale=document.createElement('meta');locale.setAttribute('property','og:locale');document.head.append(locale)}locale.content=seo.locale;
  document.querySelector('meta[name="twitter:title"]').content=seo.title;
  document.querySelector('meta[name="twitter:description"]').content=seo.description;
  const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState({},'',url);
  localStorage.setItem('fd-language',lang);
}
$$('[data-lang]').forEach(button=>button.addEventListener('click',()=>applyLanguageSeo(button.dataset.lang)));
const initialLang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('fd-language')||'en';
if(/^(en|fa|ar)$/.test(initialLang)){const initialButton=document.querySelector(`[data-lang="${initialLang}"]`);if(initialButton)initialButton.click();else applyLanguageSeo(initialLang)}
